<script lang="ts">
  import { onMount } from 'svelte'; import { Button } from 'm3-svelte';
  import { api, errorMessage, type Key, type Project, type Service } from '$lib/api';
  let keys: Key[] = []; let projects: Project[] = []; let services: Service[] = []; let loading = true; let loaded = false; let busy = false; let error = ''; let secret = ''; let copyMessage = '';
  let name = ''; let project = ''; let allowed: string[] = []; let expires = '';
  async function load() { loading = true; loaded = false; error = ''; try { const [k, p, s] = await Promise.all([api.keys(), api.projects(), api.services()]); keys = k.keys; projects = p.projects; services = s.services; loaded = true; } catch (e) { error = errorMessage(e); } finally { loading = false; } }
  async function create() { busy = true; error = ''; secret = ''; try { const result = await api.createKey({ name, project_id: project, allowed_services: allowed, expires_at: expires ? new Date(expires).toISOString() : null }); secret = result.secret; name = ''; expires = ''; allowed = []; loaded = false; keys = (await api.keys()).keys; loaded = true; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function revoke(key: Key) { if (!confirm(`Revoke ${key.name}? Access may remain until the gateway picks up the change.`)) return; busy = true; error = ''; try { await api.revokeKey(key.id); loaded = false; keys = (await api.keys()).keys; loaded = true; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function copy() { try { await navigator.clipboard.writeText(secret); copyMessage = 'Copied to clipboard.'; } catch { copyMessage = 'Copy failed. Select and copy the secret manually.'; } }
  onMount(load);
</script>
<div class="page"><div class="heading"><div><h1>API keys</h1><p class="subtitle">Issue and revoke access for your projects. Gateway projection may take time to become effective.</p></div><Button variant="outlined" onclick={load}>Refresh</Button></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if secret}<div class="notice" role="status"><strong>Save this key now.</strong> It cannot be retrieved again.<pre class="secret">{secret}</pre><div class="actions"><Button variant="outlined" onclick={copy}>Copy key</Button><Button variant="text" onclick={() => { secret = ''; copyMessage = ''; }}>Dismiss</Button><span>{copyMessage}</span></div></div>{/if}
<section><h2>Your keys</h2>{#if loading}<p role="status">Loading keys…</p>{:else if loaded && !keys.length}<p class="muted">No keys returned.</p>{:else if loaded}<div class="table-wrap"><table><thead><tr><th>Name</th><th>Project</th><th>Allowed services</th><th>Expires</th><th>State</th><th>Action</th></tr></thead><tbody>{#each keys as key}<tr><td>{key.name}</td><td>{projects.find(p => p.id === key.project_id)?.name || key.project_id}</td><td>{key.allowed_services.join(', ') || 'None'}</td><td>{key.expires_at ? new Date(key.expires_at).toLocaleString() : 'No expiry'}</td><td>{key.revocation_state}</td><td><Button variant="text" disabled={busy} onclick={() => revoke(key)}>Revoke</Button></td></tr>{/each}</tbody></table></div>{/if}</section>
<section class="section"><h2>Create a key</h2><form class="panel form stack" onsubmit={(event) => { event.preventDefault(); create(); }}><label>Name<input required bind:value={name} /></label><label>Project<select required bind:value={project}><option value="" disabled>Select a project</option>{#each projects as item}<option value={item.id}>{item.name} · {item.team}</option>{/each}</select></label><label>Allowed services<select multiple bind:value={allowed} required>{#each services as item}<option value={item.name}>{item.name}</option>{/each}</select></label><span class="muted">Select one or more services. Use Ctrl or Command to select multiple.</span><label>Expires at (optional)<input type="datetime-local" bind:value={expires} /></label><div><Button disabled={busy || loading} type="submit">Create key</Button></div></form></section></div>
